# Simple matrix implementation for testing the fix without import issues
class SimpleMatrix:
    def __init__(self, rows, cols, data=None):
        self.rows = rows
        self.cols = cols
        if data is None:
            self._data = [[0 for _ in range(cols)] for _ in range(rows)]
        elif callable(data):
            self._data = [[data(i, j) for j in range(cols)] for i in range(rows)]
        else:
            self._data = data

    def __getitem__(self, key):
        i, j = key
        return self._data[i][j]

    def __setitem__(self, key, value):
        i, j = key
        self._data[i][j] = value

    def _new(self, rows, cols, entry_func):
        return SimpleMatrix(rows, cols, entry_func)

    def col_insert(self, pos, other):
        """Implementation using the FIXED logic"""
        def entry(i, j):
            if j < pos:
                return self[i, j]
            elif pos <= j < pos + other.cols:
                return other[i, j - pos]
            return self[i, j - other.cols]  # FIXED: was j - pos - other.cols

        return self._new(self.rows, self.cols + other.cols, entry)

    def __str__(self):
        result = []
        for i in range(self.rows):
            row = [str(self._data[i][j]) for j in range(self.cols)]
            result.append('[' + ', '.join(f'{x:>2}' for x in row) + ']')
        return '\n'.join(result)

def create_identity(n):
    """Create an identity matrix"""
    def entry(i, j):
        return 1 if i == j else 0
    return SimpleMatrix(n, n, entry)

def create_ones(rows, cols):
    """Create a matrix of ones"""
    def entry(i, j):
        return 1
    return SimpleMatrix(rows, cols, entry)

def test_col_insert_bug_fix():
    """Test the specific bug case from the issue"""
    print("Testing the Matrix.col_insert() bug fix")
    print("="*50)

    # Create a 6x6 identity matrix
    M = create_identity(6)
    print("Original 6x6 identity matrix:")
    print(M)
    print()

    # Create a 6x2 matrix of 2s (representing 2 * ones(6, 2))
    V = SimpleMatrix(6, 2)
    for i in range(6):
        for j in range(2):
            V[i, j] = 2

    print("6x2 matrix to insert (filled with 2s):")
    print(V)
    print()

    # Insert columns at position 3
    result = M.col_insert(3, V)
    print("Result after col_insert(3, V):")
    print(result)
    print(f"Result shape: {result.rows}x{result.cols}")
    print()

    # Verify the result
    print("Verification:")
    success = True

    # Check identity elements that should remain unchanged (columns 0,1,2)
    for i in range(6):
        for j in range(3):
            expected = 1 if i == j else 0
            actual = result[i, j]
            if actual != expected:
                print(f"❌ result[{i},{j}] = {actual}, expected {expected}")
                success = False

    # Check inserted elements (columns 3,4)
    for i in range(6):
        for j in range(3, 5):
            expected = 2
            actual = result[i, j]
            if actual != expected:
                print(f"❌ result[{i},{j}] = {actual}, expected {expected}")
                success = False

    # Check shifted identity elements (columns 5,6,7)
    for i in range(6):
        for j in range(5, 8):
            orig_col = j - 2  # These should map to original columns 3,4,5
            expected = 1 if i == orig_col else 0
            actual = result[i, j]
            if actual != expected:
                print(f"❌ result[{i},{j}] = {actual}, expected {expected} (should map to orig col {orig_col})")
                success = False

    if success:
        print("✅ All tests passed! The fix is working correctly.")
    else:
        print("❌ Some tests failed!")

    return success

if __name__ == "__main__":
    test_col_insert_bug_fix()

